请对以下 case 进行三维加权评分。

=== case_id ===
Case-03-anti-addiction-006

=== 用户原始指令 (query.txt) ===
搞个防沉迷卡片 上面有个按钮 中间一句话带数字 点一下能进去 还有红色那种危险提示

=== TaskSpec 契约 (task.taskSpec.json) ===
{
  "userQuery": "搞个防沉迷卡片 上面有个按钮 中间一句话带数字 点一下能进去 还有红色那种危险提示",
  "size": "2x2",
  "eventCandidates": [
    {
      "call": "clickToDeeplink",
      "args": {
        "bundleName": "com.huawei.hmos.settings",
        "abilityName": "com.huawei.hmos.settings.MainAbility",
        "uri": "parent_control"
      }
    }
  ],
  "dataModelSchema": {
    "antiAddiction": {
      "title": {
        "type": "string",
        "description": "防沉迷卡片标题",
        "sampleValue": "防沉迷"
      },
      "actionLabel": {
        "type": "string",
        "description": "进入健康使用 App 设置页的按钮文案",
        "sampleValue": "去设置"
      },
      "primaryText": {
        "type": "string",
        "description": "包含数字的使用时长提示语",
        "sampleValue": "今日已用 42 分钟"
      },
      "riskText": {
        "type": "string",
        "description": "红色危险提示文案",
        "sampleValue": "超时风险"
      }
    }
  },
  "assetCandidates": [
    {
      "src": "resources/base/media/icon_timing.png",
      "description": "防沉迷场景的计时图标，可用于表达应用使用时长、限制计时或家长控制状态。"
    }
  ]
}

